    'RegistrationText'=>'A les instàncies de SimpleRisk registrades se\'ls concedeix accés immediatament a l\'Extres d\'actualització i marc de control segur (SCF). L\'actualització addicional ofereix la possibilitat de fer una còpia de seguretat i actualitzar la vostra instància de SimpleRisk amb el clic d\'un botó. El Secure Controls Framework (SCF) Extra proporciona un marc de control comú que s\'integra a la funcionalitat SimpleRisk Governance. En registrar SimpleRisk, la vostra informació de registre s\'enviarà a un servidor allotjat per SimpleRisk. La informació de registre proporcionada serà utilitzada per SimpleRisk per notificar als clients les noves versions i les actualitzacions de seguretat. L\'acte de registrar SimpleRisk us permetrà participar en les nostres comunicacions de màrqueting, però podeu desactivar-vos en qualsevol moment mitjançant l\'enllaç de cancel·lació de la subscripció d\'aquestes comunicacions. SimpleRisk respecta la privadesa dels nostres clients i la informació que ens proporcionen mitjançant el procés de registre de SimpleRisk mai es vendrà a un tercer.',
