    // Configure Hub - tile descriptions (system category)
    'SettingsDesc'                        => 'Configura els paràmetres de tot el sistema: URL base, seguretat, idioma predeterminat, zona horària, valors predeterminats de puntuació de risc i més.',
    'SettingsPreferencesDesc'             => 'Valors predeterminats i preferències de comportament a SimpleRisk: idioma, zona horària, estats d\'auditoria, requisits de mapatge de riscos, activacions/desactivació del comportament de la interfície d\'usuari i similars.',
    'SettingsFileUploadDesc'              => 'Tipus de càrrega de fitxers permesos i límits de mida per als diversos camps de fitxers adjunts.',
    'SettingsMailDesc'                    => 'Configuració SMTP per a notificacions de correu electrònic sortints, incloent-hi el transport, l\'amfitrió, l\'autenticació i la resposta.',
    'SettingsBackupsDesc'                 => 'Configura la retenció de còpies de seguretat, la programació i els enllaços de descàrrega per a les còpies de seguretat de la base de dades SimpleRisk.',
    'SettingsSecurityDesc'                => 'Configuració de seguretat de l\'autenticació, la sessió, la política de contrasenyes, l\'URL base i l\'API.',
    'SettingsLoggingDesc'                 => 'Configuració del registre de depuració i auditoria: nivells de registre, retenció i ubicació dels fitxers de registre.',
    'HealthCheckDesc'                     => 'Diagnosticar l\'estat del sistema: versió de PHP, extensions, permisos de fitxers, connectivitat de la base de dades, programació cron i activacions addicionals.',
    'AnnouncementsDesc'                   => 'Redacta i gestiona anuncis de bàner visibles per a tots els usuaris.',
    'RegisterAndUpgradeDesc'              => 'Registra la teva instal·lació de SimpleRisk, introdueix o renova una clau de subscripció i activa les actualitzacions Core/Extra amb un sol clic.',
    'QueueMonitorDesc'                    => 'Inspeccioneu la cua de treballs en segon pla: treballs pendents, en curs i fallits.',
    'ExtrasDesc'                          => 'Activar, desactivar i configurar SimpleRisk Extras (complements de pagament).',
    'ArtificialIntelligenceExtraDesc'     => 'L\'Artificial Intelligence Extra proporciona una anàlisi de riscos millorada (incloses les avaluacions FAIR) i documentació personalitzada.',
    'CustomizationExtraDesc'              => 'L\'extra de personalització permet afegir i eliminar diferents tipus de camps i crear dinàmicament plantilles de pàgina personalitzades.',
    'NotificationExtraDesc'               => 'L\'extra de notificacions per correu electrònic permet a SimpleRisk enviar notificacions per correu electrònic quan s\'envien, es modifiquen o es prenen mesures per a riscos. Aquest extra també es pot afegir com a script programat per enviar recordatoris rutinaris quan els riscos estan preparats per a una revisió de la direcció. Al producte SimpleRisk Core, sense aquest extra, no es comuniquen notificacions fora de la pròpia eina.',
    'VulnerabilityManagementExtraDesc'    => 'Vulnerability Management Extra ofereix als clients la possibilitat d\'integrar la seva instància de SimpleRisk amb Qualys, Tenable.io o Rapid7 Nexpose/InsightVM i importar dades d\'actius i vulnerabilitats a SimpleRisk. Des d\'allà, podeu seleccionar quins llocs voleu cobrir, determinar quines puntuacions de vulnerabilitat s\'han d\'importar i classificar quines vulnerabilitats es converteixen en riscos per fer-ne un seguiment.',
    'IncidentManagementExtraDesc'         => 'L\'Incident Management Extra es basa en la Guia de gestió d\'incidents de seguretat informàtica NIST 800-61 i proporciona funcions de gestió d\'incidents des del sistema SimpleRisk.',

    // Configure Hub - tile descriptions (customization category)
    'RedefineNamingConventionsDesc'       => 'Canvieu el nom de la terminologia de SimpleRisk (Risc, Actiu, Marc de treball, etc.) a la interfície d\'usuari.',
    'RiskConfigurationDesc'               => 'Configura les regles de puntuació de risc: nivells, apetit, llindars de SLA i les fórmules de risc clàssiques/contributives.',
    'RiskAndThreatCatalogDesc'            => 'Mantingueu el catàleg de valors de risc i amenaça utilitzats als menús desplegables.',
    'AddAndRemoveValuesDesc'              => 'Gestioneu els valors desplegables dels camps de risc: ubicació, origen, categoria, equip, tecnologia i més.',
    'AssetValuationDesc'                  => 'Configureu l\'escala de valoració d\'actius i les substitucions de valoració per actiu.',

    // Configure Hub - tile descriptions (users category)
    'UserManagementDesc'                  => 'Afegir, editar, desactivar i restablir usuaris; gestionar la política de contrasenyes.',
    'RoleManagementDesc'                  => 'Definir els rols i els permisos que atorga cada rol.',
    'TeamManagementDesc'                  => 'Crea i gestiona equips utilitzats per al filtratge de visibilitat de registres.',
    'SeparationExtraDesc'                 => 'L\'Extra de separació basada en equips restringeix la visualització de riscos només als usuaris que són membres de l\'equip al qual s\'ha assignat el risc. Al producte SimpleRisk Core, sense aquest Extra, tots els usuaris poden veure tots els riscos.',
    'CustomAuthenticationExtraDesc'       => 'L\'Extra d\'autenticació personalitzada proporciona compatibilitat amb l\'autenticació d\'Active Directory i SAML. Al producte SimpleRisk Core, sense aquest Extra, l\'única opció és crear nous usuaris al repositori d\'identitats de SimpleRisk.',
    'EncryptionExtraDesc'                 => 'L\'Encrypted Database Extra genera una clau de xifratge AES-256 bits aleatòria i la utilitza per xifrar text confidencial abans d\'inserir-lo a la base de dades SimpleRisk. Això impedeix que ningú pugui veure o modificar les dades sense utilitzar directament l\'aplicació SimpleRisk.',
    'OrganizationManagementDesc'          => "L'Extra de Jerarquia Organitzativa permet definir diverses unitats de negoci que poden incloure qualsevol nombre d'equips. Aleshores, els usuaris poden ser assignats a un o més equips sota diverses unitats de negoci. Això afecta la capacitat d'un usuari per veure i utilitzar els equips, els usuaris i els actius amb els quals no està associat.",

    // Configure Hub - tile descriptions (data category)
    'DeleteRisksDesc'                     => 'Elimineu riscos en massa. Feu servir amb moderació: les eliminacions són permanents.',
    'AuditTrailDesc'                      => 'Cerca i exporta el registre d\'auditoria del sistema de les accions de l\'usuari.',
    'ImportExportExtraDesc'               => 'L\'Extra d\'Importació-Exportació ofereix la possibilitat d\'importar dades a SimpleRisk assignant camps d\'un fitxer CSV a camps de la base de dades SimpleRisk. Es pot utilitzar per importar resultats d\'auditoria d\'un full de càlcul de tercers, resultats d\'escaneig de vulnerabilitats d\'una altra eina, actius de la vostra CMDB i més. L\'Extra també ofereix la possibilitat d\'exportar fitxers CSV des de SimpleRisk que continguin riscos, mitigacions, revisions o un informe combinat dels tres.',
    'JiraExtraDesc'                       => 'Jira Integration Extra ofereix als usuaris la possibilitat d\'integrar-se bidireccionalment amb una instància de Jira. Permet connectar riscos a incidències de Jira, així com sincronitzar les seves dades, estat i comentaris.',
    'APIExtraDesc'                        => 'L\'API Extra permet als clients utilitzar una API RESTful per crear interaccions amb scripts amb altres aplicacions per obtenir automatització avançada i aprofitar la infraestructura existent.',
    'AdvancedSearchExtraDesc'             => "La Cerca Avançada Extra amplia la funcionalitat del quadre de cerca de la barra superior per poder trobar riscos mitjançant una cerca textual a les dades de risc.",
    'AssessmentsExtraDesc'                => 'L\'Avaluació de Riscos Extra ofereix als usuaris la possibilitat de definir contactes, crear preguntes (inclosa la lògica), muntar diverses preguntes amb una plantilla de qüestionari, crear qüestionaris i enviar-los als contactes, visualitzar els resultats del qüestionari, afegir riscos basats en aquests resultats i comparar els resultats al llarg del temps, importar i exportar avaluacions personalitzades externament i revisar el registre d\'auditoria de l\'avaluació de riscos.',
    'ActiveAssessmentsDesc'               => 'Visualitza i gestiona les avaluacions actualment en curs.',
    'WorkflowsExtraDesc'                  => 'Workflows Extra proporciona un motor de flux de treball visual basat en esdeveniments que automatitza les accions de gestió de riscos en resposta a esdeveniments dins de SimpleRisk. Podeu dissenyar fluxos de treball que es desencadenen en canvis, com ara l\'enviament, l\'actualització o la revisió d\'un risc, per encaminar aprovacions, assignar treball i mantenir el procés en moviment sense intervenció manual.',

    // Configure Hub - tile descriptions (frameworks category)
    'UCFExtraDesc'                        => 'L\'Unified Compliance Framework (UCF) Extra és una integració a nivell d\'API entre l\'Unified Compliance Framework i SimpleRisk. Si l\'activeu, podeu importar marcs de treball seleccionats i assignacions de control directament des de l\'UCF.',
    'SCFExtraDesc'                        => "El Secure Controls Framework (SCF) Extra és una integració directa entre el Secure Controls Framework i SimpleRisk. Importa el catàleg de controls de l'SCF i les seves assignacions a través d'una àmplia gamma de marcs de compliment i ciberseguretat a la funcionalitat de governança de SimpleRisk, de manera que podeu adoptar els marcs que necessiteu i gestionar els seus controls sense haver de construir-los manualment.",

    // Configure Hub - tile descriptions (maintenance category)
    'FixReviewDatesDesc'                  => 'Migra les columnes de data de revisió varchar heretades als tipus de data adequats. Només visible quan calgui.',
