    'EncryptionRestoreBodyWhat'             => 'Totes les files escrites a la base de dades després de la creació de la còpia de seguretat es perdran permanentment, inclosos els riscos, les mitigacions, les entrades del registre d\'auditoria i qualsevol altre canvi realitzat des de l\'activació. L\'extra de la base de dades xifrada es desactivarà com a part de la restauració.',
